PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (user_id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS songs (song_id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, movie_name TEXT, singer TEXT, language TEXT NOT NULL DEFAULT 'Hindi', cover_image_url TEXT, provider TEXT, external_url TEXT, embed_url TEXT, created_by INTEGER REFERENCES users(user_id) ON DELETE SET NULL, approval_status TEXT NOT NULL DEFAULT 'approved', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS song_categories (assignment_id INTEGER PRIMARY KEY AUTOINCREMENT, song_id INTEGER NOT NULL REFERENCES songs(song_id) ON DELETE CASCADE, mood TEXT NOT NULL, time_category TEXT NOT NULL, period TEXT NOT NULL, language TEXT NOT NULL DEFAULT 'Hindi', is_featured INTEGER NOT NULL DEFAULT 0, UNIQUE(song_id, mood, time_category, period));
CREATE TABLE IF NOT EXISTS playlists (playlist_id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT, cover_image_url TEXT, mood TEXT, time_category TEXT, period TEXT, visibility TEXT NOT NULL DEFAULT 'private', share_token TEXT UNIQUE, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS playlist_songs (playlist_id INTEGER NOT NULL REFERENCES playlists(playlist_id) ON DELETE CASCADE, song_id INTEGER NOT NULL REFERENCES songs(song_id) ON DELETE CASCADE, position INTEGER NOT NULL, added_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(playlist_id, song_id), UNIQUE(playlist_id, position));
CREATE TABLE IF NOT EXISTS favorites (user_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, song_id INTEGER NOT NULL REFERENCES songs(song_id) ON DELETE CASCADE, created_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id, song_id));
CREATE TABLE IF NOT EXISTS journal_entries (entry_id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, title TEXT NOT NULL, content TEXT NOT NULL, mood TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stories (story_id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER REFERENCES users(user_id) ON DELETE SET NULL, title TEXT NOT NULL, content TEXT NOT NULL, category TEXT, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS comments (comment_id INTEGER PRIMARY KEY AUTOINCREMENT, story_id INTEGER NOT NULL REFERENCES stories(story_id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, content TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS story_reactions (story_id INTEGER NOT NULL REFERENCES stories(story_id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, reaction TEXT NOT NULL DEFAULT 'heart', created_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(story_id, user_id, reaction));
CREATE TABLE IF NOT EXISTS reports (report_id INTEGER PRIMARY KEY AUTOINCREMENT, reporter_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, story_id INTEGER NOT NULL REFERENCES stories(story_id) ON DELETE CASCADE, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mood_logs (log_id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, mood TEXT NOT NULL, note TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_songs_status ON songs(approval_status);
CREATE INDEX IF NOT EXISTS idx_categories_filter ON song_categories(time_category, period, mood, language);
CREATE INDEX IF NOT EXISTS idx_stories_status ON stories(status, created_at);
